def end_weight_update(self):
    """Close the weight-update session (post-load + quant post-process on the full model)."""
    return self._optional_weight_session_request("end_weight_update")

def _optional_weight_session_request(self, endpoint: str):
    # SGLang releases before the weight-session endpoints (e.g. 0.5.15) have no
    # packed or quantized weights to restore, so the session is a no-op there.
    try:
        return self._make_request(endpoint, {})
    except requests.exceptions.HTTPError as e:
        if e.response is not None and e.response.status_code == 404:
            if not getattr(self, "_weight_session_unsupported_logged", False):
                logger.info("SGLang server has no /%s endpoint; treating weight session as a no-op", endpoint)
                self._weight_session_unsupported_logged = True
            return None
        raise

def update_weight_version(self, weight_version: str):
    return self._make_request(
        "update_weight_version",
        {"new_version": weight_version},
    )

def start_profile(
    self,
    # The output directory
    output_dir: str | None = None,
    # If set, it profile as many as this number of steps.
    # If it is set, profiling is automatically stopped after this step, and
    # the caller doesn't need to run stop_profile.
    start_step: int | None = None,
    num_steps: int | None = None,
    activities: list[str] | None = None,
    profile_by_stage: bool = False,
    with_stack: bool | None = None,

    if "ref" in self.weights_backuper.backup_tags:
        self._set_replay_stage("fallthrough")
        self._switch_model("ref")
        rollout_data.update(
            self.compute_log_prob(
                data_iterator,
                num_microbatches,
                rollout_id=rollout_id,
                store_prefix="ref_",
            )
        )
    # Forward teacher model to get teacher_log_probs for Megatron-based OPD
    if "teacher" in self.weights_backuper.backup_tags:
        self._set_replay_stage("fallthrough")
        self._switch_model("teacher")
        rollout_data.update(
            self.compute_log_prob(
                data_iterator,
                num_microbatches,
                rollout_id=rollout_id,
                store_prefix="teacher_",
            )
        )
    self._switch_model("old_actor" if self.args.keep_old_actor else "actor")
    if not self.args.use_rollout_logprobs or self.args.get_mismatch_metrics:
        for m in all_replay_managers:
            if m.enabled:
                if self._use_rollout_replay(m):
                    m.stage = "replay_forward"
                else:
                    m.stage = "record"
        rollout_data.update(
            self.compute_log_prob(
                data_iterator,
                num_microbatches,
                rollout_id=rollout_id,
                store_prefix="",
            )
        )
        for m in all_replay_managers:
            if self._use_rollout_replay(m):
                m.clear_all_forward()
    torch.cuda.empty_cache()

    if self.args.use_critic:
        sync_actor_critic_data(
            self.args,
            rollout_data,
            self._actor_critic_groups,
        )
    if self._active_model_tag != "actor":
        self._switch_model("actor")

    # Calculate adv and returns. Need to performed before training (instead of on the fly),
    # because we may need normalize the whole rollout.
    compute_advantages_and_returns(self.args, rollout_data)
    log_train_advantage_computation_event(rollout_data)

if self.rollout_data_postprocess is not None:
    self.rollout_data_postprocess(self.args)

