python3 -I - <<'PY'
import glob,json,gzip,collections
rows=[]
for f in glob.glob('logs/public_rerun/turns/*.jsonl.gz'):
 with gzip.open(f,'rt') as h: rows += [json.loads(x) for x in h]
g=collections.defaultdict(dict)
for r in rows:
 if r['event']=='generate':g[r['session']][r['turn']]=r
for t in range(1,7):
 xs=[]
 for turns in g.values():
  if t in turns and t-1 in turns:
   a,b=turns[t-1],turns[t]
   xs.append((b['cached_tokens']-a['cached_tokens'])/(a['prompt_tokens']+a['completion_tokens']))
 print('turn',t-1,'to',t,'median incremental cache fraction',round(sorted(xs)[len(xs)//2],3),'zero fraction',round(sum(x==0 for x in xs)/len(xs),3))
PY

