   a,b=turns[t-1],turns[t]
   xs.append((b['cached_tokens']-a['cached_tokens'])/(a['prompt_tokens']+a['completion_tokens']))
 print('turn',t-1,'to',t,'median incremental cache fraction',round(sorted(xs)[len(xs)//2],3),'zero fraction',round(sum(x==0 for x in xs)/len(xs),3))
PY

